import{_ as a,o as t,c as i,a6 as n}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Contrats Cloud, synchronisation et examen","description":"","frontmatter":{"title":"Contrats Cloud, synchronisation et examen","docId":"developer.cloud","translationKey":"developer.cloud","locale":"fr","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"06ae46545d1366d4f456c78a0e6583ea0338afbd496467e4d25b3abe1a5430fb","translationRevision":"2cc81ecc7fd36c99e129ac480ec73e673e79ccf136a296143e2d670fa0e7dbd0","order":180},"headers":[],"relativePath":"fr/developer/cloud.md","filePath":"fr/developer/cloud.md","lastUpdated":1794611623000}'),s={name:"fr/developer/cloud.md"};function r(o,e,l,c,d,u){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="cloud-contracts-synchronization-and-review" tabindex="-1">Contrats Cloud, synchronisation et examen <a class="header-anchor" href="#cloud-contracts-synchronization-and-review" aria-label="Permalink to &quot;Contrats Cloud, synchronisation et examen {#cloud-contracts-synchronization-and-review}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Développer les fonctionnalités de configuration de compte et de catalogue pour l’instance Cloud provisionnée. Le fonctionnement uniquement local reste valide. Pour le travail authentifié, utilisez un compte et un serveur de test dédiés ainsi que le transfert de session natif ; cette documentation n’établit pas la validation des jetons porteurs en production ou de deux appareils.</p><p>Le propriétaire vérifié des contrats est <a href="https://github.com/nglmercer/RemakeBackend" target="_blank" rel="noreferrer">nglmercer/RemakeBackend</a>, avec les <a href="https://github.com/nglmercer/RemakeBackend/blob/master/docs/CLOUD-API-V2.md" target="_blank" rel="noreferrer">contrats de configuration v2</a> et les <a href="https://github.com/nglmercer/RemakeBackend/blob/master/docs/CLOUD-API-V3.md" target="_blank" rel="noreferrer">interfaces v3</a> additives. Les types portables appartenant au serveur et le transport client sont représentés localement dans <code>crates/cloud-contracts</code> et <code>crates/cloud-client</code>. La durabilité et l’authentification du bureau restent des responsabilités de l’hôte.</p><h2 id="gate-and-stage-operations" tabindex="-1">Conditionner et préparer les opérations <a class="header-anchor" href="#gate-and-stage-operations" aria-label="Permalink to &quot;Conditionner et préparer les opérations {#gate-and-stage-operations}&quot;">​</a></h2><ol><li>Découvrez les méthodes natives avec <code>rpc.discover</code> ; un ancien hôte peut conserver les vues héritées.</li><li>Laissez l’hôte vérifier <code>/api/v2/capabilities</code> de l’instance avant d’utiliser un point de terminaison conditionné par capacité. Ne codez jamais en dur une capacité annoncée par le serveur dans un simple indicateur du navigateur.</li><li>Utilisez l’origine provisionnée par l’opérateur. Les compilations de publication n’acceptent pas de remplacements arbitraires d’origine à l’exécution.</li><li>Prévisualisez migration et conflits, conservez les bases figées et écritures incertaines, et soumettez uniquement l’opération examinée.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync.v2.migrate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> globals.typed.replace</span></span></code></pre></div><p>Ces commandes examinent les schémas ; elles ne migrent pas de compte et n’enregistrent pas de valeurs de variables.</p><h2 id="current-implementation" tabindex="-1">Implémentation actuelle <a class="header-anchor" href="#current-implementation" aria-label="Permalink to &quot;Implémentation actuelle {#current-implementation}&quot;">​</a></h2><p>V2 dispose d’un état/stockage/coordinateur natif, d’une migration v1 protégée, d’un examen des conflits, d’une reconstruction et de parcours de rapprochement des plugins installés. L’adoption est explicite et limitée au compte ; les anciennes installations non marquées conservent leur parcours historique. La validation complète de deux bureaux et certains adaptateurs produit restent incomplets. La configuration d’époque d’écriture à l’échelle du compte a des conséquences serveur irréversibles expliquées par son examen de migration.</p><p>V3 ajoute catalogue, équipes, intégrations, ressources, incrustations et paquets derrière des capacités. Les métadonnées de catalogue ne remplacent pas la vérification signée des plugins. L’importation utilise le journal du propriétaire ; examinez enabled à l’application/import de profil. L’application des paquets enregistre les étapes interrompues au lieu de les rejouer automatiquement. L’accès en lecture au relais Cloud ne doit pas être confondu avec l’autorité de mutation de collaboration directe.</p><h2 id="expected-result-and-recovery" tabindex="-1">Résultat attendu et récupération <a class="header-anchor" href="#expected-result-and-recovery" aria-label="Permalink to &quot;Résultat attendu et récupération {#expected-result-and-recovery}&quot;">​</a></h2><p>Les changements de configuration conservent les frontières d’identité, de révision et d’examen. Automations Changes est uniquement local ; Variables avec examen utilise de vraies méthodes natives typées et ne synchronise pas les valeurs brutes. Overlay Changes n’est pas fusionné. En cas de conflit, comparez les enregistrements de base, locaux et Cloud récents ; en cas d’accusé inconnu, résolvez l’intention conservée. Une erreur HTTP autorisant une nouvelle tentative n’autorise jamais à répéter une mutation. La <a href="./collaboration.html">collaboration</a> couvre séparément l’autorité de l’hôte actif.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p><code>TIKTOOLS_CLOUD_ORIGIN</code> suit runtime → valeur compilée → défaut en debug, mais compilée → défaut en release, qui ignore les variables runtime. Vide, <code>off</code>, <code>none</code> désactivent seulement à la couche applicable. Valeur admise : origine HTTPS sans identifiants/chemin/query/fragment ; HTTP uniquement loopback explicite. Debug isolé : <code>TIKTOOLS_CLOUD_ORIGIN=http://127.0.0.1:8787 bun run start</code> ; release : <code>TIKTOOLS_CLOUD_ORIGIN=https://cloud.example bun scripts/task.ts rust build -p tiktools-desktop --release --locked</code>. Une identité d’une autre origine ne se restaure pas : vérifiez origine/compte avant authentification. Un défaut compilé ne prouve pas la disponibilité.</p><p>Suivez <a href="./../user/cloud/changes.html#operational-details">migration et récupération par mode</a>. Coordonnez tous les appareils avant la politique d’époque irréversible, gardez comptes/résultats et relisez l’état après barrière ambiguë sans la répéter pour savoir si elle a réussi. La récupération fige entrées et révision examinées ; une revue périmée doit être refaite avant reprise, qui n’envoie pas d’écriture Cloud.</p>`,16)])])}const h=a(s,[["render",r]]);export{m as __pageData,h as default};
